content.content:
1	$base = "D:\.claude"
2	$timestamp = Get-Date -Format "yyyy-MM-dd HH:mm"
3	$logFile = "$base\cleanup.log"
4	
5	# --- SessionEnd payload 수신 (end_reason 등 활용 가능) ---
6	$hookData = $null
7	try {
8	    $rawInput = [Console]::In.ReadToEnd()
9	    if ($rawInput) { $hookData = $rawInput | ConvertFrom-Json }
10	} catch {}
11	
12	# --- Project Registry 읽기 ---
13	$registryPath = "$base\active-projects.json"
14	$registry = if (Test-Path $registryPath) {
15	    Get-Content $registryPath -Raw | ConvertFrom-Json
16	} else { $null }
17	$pinned = if ($registry -and $registry.pinned) { $registry.pinned } else { @() }
18	
19	# --- plans/: 2일 이상 된 파일 삭제 ---
20	$plansDeleted = 0
21	Get-ChildItem "$base\plans" -File -ErrorAction SilentlyContinue |
22	    Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-2) } |
23	    ForEach-Object { Remove-Item $_.FullName -Force; $plansDeleted++ }
24	
25	# --- shell-snapshots/: 7일 이상 된 파일 삭제 ---
26	$ssDeleted = 0
27	Get-ChildItem "$base\shell-snapshots" -File -ErrorAction SilentlyContinue |
28	    Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-7) } |
29	    ForEach-Object { Remove-Item $_.FullName -Force; $ssDeleted++ }
30	
31	# --- file-history/: 14일 이상 된 UUID 디렉토리 삭제 ---
32	$fhDeleted = 0
33	Get-ChildItem "$base\file-history" -Directory -ErrorAction SilentlyContinue |
34	    Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-14) } |
35	    ForEach-Object { Remove-Item $_.FullName -Recurse -Force; $fhDeleted++ }
36	
37	# --- projects/: Registry + recency 기반 보호 (OCP/DIP 준수) ---
38	$projDeleted = 0
39	Get-ChildItem "$base\projects" -Directory -ErrorAction SilentlyContinue |
40	    Where-Object {
41	        $name = $_.Name
42	        $isPinned = $pinned | Where-Object { $name -like "*$_*" }
43	        $isRecent = $_.LastWriteTime -gt (Get-Date).AddDays(-14)
44	        -not $isPinned -and -not $isRecent -and
45	        $_.LastWriteTime -lt (Get-Date).AddDays(-30)
46	    } |
47	    ForEach-Object { Remove-Item $_.FullName -Recurse -Force; $projDeleted++ }
48	
49	# --- session-env/: 빈 서브디렉토리 제거 ---
50	$seDeleted = 0
51	Get-ChildItem "$base\session-env" -Directory -ErrorAction SilentlyContinue |
52	    Where-Object { (Get-ChildItem $_.FullName -Force).Count -eq 0 } |
53	    ForEach-Object { Remove-Item $_.FullName -Force; $seDeleted++ }
54	
55	# --- MEMORY.md 참조 무결성 체크 (모든 프로젝트 순회) ---
56	Get-ChildItem "$base\projects" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
57	    $memoryDir = Join-Path $_.FullName "memory"
58	    $memIndex = Get-Content "$memoryDir\MEMORY.md" -ErrorAction SilentlyContinue
59	    if ($memIndex) {
60	        $memIndex | Select-String '\[.*\]\(([^)]+\.md)\)' | ForEach-Object {
61	            $ref = $_.Matches[0].Groups[1].Value
62	            if ($ref -notlike 'http*' -and -not (Test-Path "$memoryDir\$ref")) {
63	                "[$timestamp] WARN: MEMORY.md ($($memoryDir)) references missing file: $ref" | Add-Content $logFile
64	            }
65	        }
66	    }
67	}
68	
69	# --- 감사 로그 기록 (공식 SessionEnd 필드는 source, 구버전 end_reason 도 호환) ---
70	$endReason = if ($hookData -and $hookData.source) { $hookData.source }
71	              elseif ($hookData -and $hookData.end_reason) { $hookData.end_reason }
72	              else { "unknown" }
73	"[$timestamp] end:$endReason plans:$plansDeleted shell-snapshots:$ssDeleted file-history:$fhDeleted projects:$projDeleted session-env:$seDeleted" |
74	    Add-Content $logFile
75

1	# Detached worker: fetch Claude Code release tag + key official docs, diff against
2	# cached SHA256, append change notes to D:\.claude\docs-updates.md.
3	# No auto-edits to CLAUDE.md / AGENTS.md --surface only, user decides.
4	
5	$ErrorActionPreference = 'SilentlyContinue'
6	
7	[Net.ServicePointManager]::SecurityProtocol = `
8	    [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
9	
10	$cacheDir = 'D:\.claude\.docs-cache'
11	$updatesFile = 'D:\.claude\docs-updates.md'
12	$today = Get-Date -Format 'yyyy-MM-dd'
13	$changes = @()
14	
15	function Save-Hash {
16	    param([string]$path, [string]$value)
17	    Set-Content -Path $path -Value $value -Encoding UTF8
18	}
19	
20	function Get-CachedHash {
21	    param([string]$path)
22	    if (Test-Path $path) { return (Get-Content $path -Raw).Trim() }
23	    return ''
24	}
25	
26	function Get-ContentHash {
27	    param([byte[]]$bytes)
28	    $sha = [Security.Cryptography.SHA256]::Create()
29	    $hash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '')
30	    $sha.Dispose()
31	    return $hash
32	}
33	
34	# 1. Claude Code CLI release tag
35	try {
36	    $headers = @{ 'User-Agent' = 'claude-code-docs-watcher' }
37	    $rel = Invoke-RestMethod 'https://api.github.com/repos/anthropics/claude-code/releases/latest' `
38	        -Headers $headers -TimeoutSec 8
39	    $tagFile = Join-Path $cacheDir 'release-tag.txt'
40	    $cached = Get-CachedHash $tagFile
41	    if ($rel.tag_name -and $rel.tag_name -ne $cached) {
42	        if ($cached -ne '') {
43	            $changes += "- **Claude Code release**: $($rel.tag_name) (was: $cached) -> $($rel.html_url)"
44	        }
45	        Save-Hash $tagFile $rel.tag_name
46	    }
47	} catch { }
48	
49	# 2. Key official docs (SHA256 diff)
50	$docs = @(
51	    @{ name = 'memory';          url = 'https://code.claude.com/docs/en/memory.md' }
52	    @{ name = 'hooks';           url = 'https://code.claude.com/docs/en/hooks.md' }
53	    @{ name = 'best-practices';  url = 'https://code.claude.com/docs/en/best-practices.md' }
54	    @{ name = 'settings';        url = 'https://code.claude.com/docs/en/settings.md' }
55	    @{ name = 'context-window';  url = 'https://code.claude.com/docs/en/context-window.md' }
56	)
57	
58	foreach ($doc in $docs) {
59	    try {
60	        $resp = Invoke-WebRequest $doc.url -TimeoutSec 8 -UseBasicParsing
61	        if ($resp.StatusCode -ne 200) { continue }
62	        $bytes = if ($resp.Content -is [byte[]]) { $resp.Content } else { [Text.Encoding]::UTF8.GetBytes($resp.Content) }
63	        $hash = Get-ContentHash $bytes
64	        $hashFile = Join-Path $cacheDir "$($doc.name).sha256"
65	        $cached = Get-CachedHash $hashFile
66	        if ($hash -ne $cached) {
67	            if ($cached -ne '') {
68	                $changes += "- **Doc updated**: $($doc.name) -> $($doc.url)"
69	            }
70	            Save-Hash $hashFile $hash
71	        }
72	    } catch { }
73	}
74	
75	if ($changes.Count -gt 0) {
76	    $entry = "## $today`n" + ($changes -join "`n") + "`n"
77	    if (-not (Test-Path $updatesFile)) {
78	        $header = "# Claude Code Upstream Updates`n`nAuto-generated by SessionStart hook. Review and decide what to apply.`n`n"
79	        Set-Content -Path $updatesFile -Value ($header + $entry) -Encoding UTF8
80	    } else {
81	        Add-Content -Path $updatesFile -Value $entry -Encoding UTF8
82	    }
83	}
84	
85	exit 0
86
